1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 已有台账文件无法读取、解析，任一批次绑定的配方版本未登记，
31	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
32	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
33	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
34	func Open(dir string) (*Store, error) {
35		if dir == "" {
36			return nil, errors.New("数据位置不能为空")
37		}
38		if err := os.MkdirAll(dir, 0o755); err != nil {
39			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
40		}
41		info, err := os.Stat(dir)
42		if err != nil {
43			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
44		}
45		if !info.IsDir() {
46			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
47		}
48	
49		lockPath := filepath.Join(dir, lockFileName)
50		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
51		if err != nil {
52			return nil, fmt.Errorf("打开锁文件失败: %w", err)
53		}
54	
55		s := &Store{dir: dir, lockFile: lf}
56		if err := s.load(); err != nil {
57			lf.Close()
58			return nil, err
59		}
60		return s, nil
61	}
62	
63	// Close 释放台账占用的文件锁。
64	func (s *Store) Close() error {
65		s.mu.Lock()
66		defer s.mu.Unlock()
67		if s.lockFile == nil {
68			return nil
69		}
70		err := s.lockFile.Close()
71		s.lockFile = nil
72		return err
73	}
74	
75	func (s *Store) lockExclusive() error {
76		if s.lockFile == nil {
77			return errors.New("台账已关闭")
78		}
79		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
80			return fmt.Errorf("锁定台账失败: %w", err)
81		}
82		return nil
83	}
84	
85	func (s *Store) lockShared() error {
86		if s.lockFile == nil {
87			return errors.New("台账已关闭")
88		}
89		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
90			return fmt.Errorf("锁定台账失败: %w", err)
91		}
92		return nil
93	}
94	
95	func (s *Store) unlock() {
96		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
97	}
98	
99	func (s *Store) load() error {
100		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
101		if err != nil {
102			if os.IsNotExist(err) {
103				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
104				return nil
105			}
106			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
107		}
108		if len(data) == 0 {
109			s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
110			return nil
111		}
112		var st persistedState
113		if err := json.Unmarshal(data, &st); err != nil {
114			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
115		}
116		if st.Version != stateVersion {
117			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
118		}
119		if err := validateState(&st); err != nil {
120			return err
121		}
122		if st.Requests == nil {
123			st.Requests = map[string]*requestRecord{}
124		}
125		s.state = &st
126		return nil
127	}
128	
129	// validateState 检查台账的引用完整性与投料数量合法性：
130	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
131	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
132	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
133	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
134	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
135	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
136	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
137	func validateState(st *persistedState) error {
138		for _, b := range st.Batches {
139			if b == nil {
140				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
141			}
142			if findRecipe(st, b.RecipeNo, b.RecipeVersion) == nil {
143				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
144					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
145			}
146			if err := validateFeedings(b); err != nil {
147				return err
148			}
149		}
150		return nil
151	}
152	
153	// validateFeedings 检查一个批次内已保存投料的数量合法性。
154	// 只判断数量本身是否合法，不判断实投是否符合配方：无投料的物料
155	// 累计为零属正常，不足或超过应投量也不在此拒绝。
156	func validateFeedings(b *batchRecord) error {
157		sums := map[string]gramsMilli{}
158		for _, f := range b.Feedings {
159			if f.GramsMilli <= 0 {
160				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
161					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
162			}
163			sum := sums[f.MaterialNo]
164			if f.GramsMilli > maxGramsMilli-sum {
165				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
166					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
167			}
168			sums[f.MaterialNo] = sum + f.GramsMilli
169		}
170		return nil
171	}
172	
173	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
174	func (s *Store) persist(st *persistedState) error {
175		data, err := json.MarshalIndent(st, "", "  ")
176		if err != nil {
177			return err
178		}
179		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
180		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
181		if err != nil {
182			return err
183		}
184		if _, err := f.Write(data); err != nil {
185			f.Close()
186			return err
187		}
188		if err := f.Sync(); err != nil {
189			f.Close()
190			return err
191		}
192		if err := f.Close(); err != nil {
193			return err
194		}
195		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
196			return err
197		}
198		if d, err := os.Open(s.dir); err == nil {
199			_ = d.Sync()
200			_ = d.Close()
201		}
202		return nil
203	}
204	
205	func cloneState(st *persistedState) (*persistedState, error) {
206		data, err := json.Marshal(st)
207		if err != nil {
208			return nil, err
209		}
210		var out persistedState
211		if err := json.Unmarshal(data, &out); err != nil {
212			return nil, err
213		}
214		if out.Requests == nil {
215			out.Requests = map[string]*requestRecord{}
216		}
217		return &out, nil
218	}
219	
220	// write 是所有写入操作的统一入口：
221	//   - reqNo 为空直接报错；
222	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
223	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
224	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
225	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
226	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
227		if reqNo == "" {
228			return errors.New("请求编号不能为空")
229		}
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		if err := s.lockExclusive(); err != nil {
233			return err
234		}
235		defer s.unlock()
236	
237		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
238		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
239		if err := s.load(); err != nil {
240			return err
241		}
242	
243		payloadRaw, err := json.Marshal(payload)
244		if err != nil {
245			return err
246		}
247		payloadStr := string(payloadRaw)
248	
249		if req, ok := s.state.Requests[reqNo]; ok {
250			if req.Op != op || req.Payload != payloadStr {
251				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
252					ErrRequestConflict, reqNo, req.Op, op)
253			}
254			if err := json.Unmarshal(req.Result, out); err != nil {
255				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
256			}
257			return nil
258		}
259	
260		clone, err := cloneState(s.state)
261		if err != nil {
262			return err
263		}
264		result, err := apply(clone)
265		if err != nil {
266			return err
267		}
268		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
269		if err := s.persist(clone); err != nil {
270			return fmt.Errorf("保存台账失败: %w", err)
271		}
272		s.state = clone
273		if err := json.Unmarshal(result, out); err != nil {
274			return fmt.Errorf("解析请求结果失败: %w", err)
275		}
276		return nil
277	}
278	
279	// read 在共享锁下读取当前状态。
280	func (s *Store) read(fn func(*persistedState) error) error {
281		s.mu.Lock()
282		defer s.mu.Unlock()
283		if err := s.lockShared(); err != nil {
284			return err
285		}
286		defer s.unlock()
287		if err := s.load(); err != nil {
288			return err
289		}
290		return fn(s.state)
291	}
292	
293	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
294	
295	func buildRecipeView(r *recipeRecord) *RecipeView {
296		mats := make([]MaterialView, 0, len(r.Materials))
297		for _, m := range r.Materials {
298			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
299		}
300		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
301	}
302	
303	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
304		v := &BatchView{
305			BatchNo:         b.BatchNo,
306			RecipeNo:        r.RecipeNo,
307			RecipeVersion:   r.Version,
308			RecipeName:      r.Name,
309			PlannedPortions: b.PlannedPortions,
310			Status:          b.Status,
311			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
312			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
313		}
314	
315		for _, f := range b.Feedings {
316			v.Feedings = append(v.Feedings, FeedingView{
317				Seq:        f.Seq,
318				MaterialNo: f.MaterialNo,
319				Grams:      f.GramsMilli.String(),
320				Time:       f.Time,
321				Registrar:  f.Registrar,
322			})
323		}
324	
325		for _, m := range r.Materials {
326			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
327			if err != nil {
328				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
329			}
330			act, ok := sumMaterialGrams(b, m.MaterialNo)
331			if !ok {
332				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
333					ErrCorruptData, b.BatchNo, m.MaterialNo)
334			}
335			v.Materials = append(v.Materials, MaterialRequirement{
336				MaterialNo:      m.MaterialNo,
337				RequiredGrams:   required.String(),
338				ActualGrams:     act.String(),
339				DifferenceGrams: (act - required).String(),
340			})
341		}
342		return v, nil
343	}
344	
345	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
346		for _, r := range st.Recipes {
347			if r.RecipeNo == recipeNo && r.Version == version {
348				return r
349			}
350		}
351		return nil
352	}
353	
354	func findBatch(st *persistedState, batchNo string) *batchRecord {
355		for _, b := range st.Batches {
356			if b.BatchNo == batchNo {
357				return b
358			}
359		}
360		return nil
361	}
362	
363	// sumMaterialGrams 统计批次内某物料已登记投料的累计千分之一克数。
364	// 仅统计该物料的记录，其他物料不参与；返回 ok=false 表示仅已有记录
365	// 的合计就已经超过可表示上限（AddFeeding 的登记前校验会阻止这种状态，
366	// 这里仍防一手整数回绕）。
367	func sumMaterialGrams(b *batchRecord, materialNo string) (sum gramsMilli, ok bool) {
368		for _, f := range b.Feedings {
369			if f.MaterialNo != materialNo {
370				continue
371			}
372			if f.GramsMilli > maxGramsMilli-sum {
373				return maxGramsMilli, false
374			}
375			sum += f.GramsMilli
376		}
377		return sum, true
378	}
