191			}
192			b.Status = StatusClosed
193			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
194			if r == nil {
195				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
196					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
