263					ErrMaterialNotInRecipe, materialNo, r.RecipeNo, r.Version)
264			}
265	
266			// 上限按物料分别判断：只累计该物料已登记的投料，
267			// 其他物料的投料量不参与，也不互相抵消。
268			summed, ok := sumMaterialGrams(b, materialNo)
269			if !ok || summed > maxGramsMilli-milli {
270				return nil, fmt.Errorf("%w: 物料 %q 的数量超出范围：本次投料后累计实投将超过上限 %s 克",
271					ErrInvalidInput, materialNo, maxGramsMilli)
272			}
