46					Batches: []*batchRecord{{
47						BatchNo:         "B-bad",
48						RecipeNo:        "R1",
49						RecipeVersion:   "v9", // 从未登记
50						PlannedPortions: 2,
51						Status:          status,
52					}},
53				})
54	
55				s, err := Open(dir)
