257		}
258		if _, err := s.UpdateDraftBatch("upd-b1", "B1", "", "", 5); !errors.Is(err, ErrCorruptData) {
259			t.Fatalf("损坏台账上调整草稿应返回 ErrCorruptData，得到 %v", err)
