261		if _, err := s.CloseBatch("close-b2", "B2"); !errors.Is(err, ErrCorruptData) {
262			t.Fatalf("不能借操作完整批次绕过读取失败，得到 %v", err)
263		}
264		if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四"); !errors.Is(err, ErrCorruptData) {
265			t.Fatalf("损坏台账上投料应返回 ErrCorruptData，得到 %v", err)
266		}
267		if _, err := s.RegisterRecipe("r3", "R3", "v1", "新配方", []MaterialInput{
268			{MaterialNo: "M1", Grams: "1"},
269		}); !errors.Is(err, ErrCorruptData) {
270			t.Fatalf("损坏台账上登记配方也应失败，得到 %v", err)
271		}
272	
273		// 被拒绝的写入不留痕迹：文件内容不变，请求编号未被占用。
274		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
275		if err != nil {
276			t.Fatal(err)
277		}
278		if !bytes.Equal(after, badBytes) {
279			t.Fatalf("被拒绝的写入不应改动台账文件")
280		}
281		if bytes.Contains(after, []byte("feed-rejected")) || bytes.Contains(after, []byte("R3")) {
282			t.Fatalf("被拒绝的写入不应留下请求结果或业务记录")
283		}
284	
285		// 恢复缺失的原配方版本后，原有记录完整可用。
286		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
287			t.Fatal(err)
288		}
289		b2, err := s.GetBatch("B2")
290		if err != nil {
291			t.Fatalf("恢复后查询应成功: %v", err)
292		}
293		if b2.Status != StatusExecuting || len(b2.Feedings) != 1 || b2.Feedings[0].Grams != "5" {
294			t.Fatalf("原有投料记录应保留: %+v", b2)
295		}
296		b3, err := s.GetBatch("B3")
297		if err != nil {
298			t.Fatalf("恢复后查询已关闭批次应成功: %v", err)
299		}
300		if b3.Status != StatusClosed {
301			t.Fatalf("关闭含义不变，恢复后仍应为已关闭: %+v", b3)
302		}
303		// 损坏前已成功的请求仍可幂等重放。
304		replay, err := s.AddFeeding("feed-b2", "B2", "M1", "5", fixedTime, "张三")
305		if err != nil {
