307		}
308		if replay.Seq != 1 {
309			t.Fatalf("重放应返回第一次成功的结果，得到 seq=%d", replay.Seq)
310		}
311		// 被拒绝过的请求编号仍可用于合法提交。
312		f, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四")
313		if err != nil {
314			t.Fatalf("被拒绝的请求编号应仍可合法使用: %v", err)
315		}
316		if f.Seq != 2 || f.Grams != "1" {
317			t.Fatalf("新投料结果不正确: %+v", f)
318		}
319	}
