710				t.Fatalf("并发相同请求应全部成功（重放），得到 %v", err)
711			}
712		}
713	
714		got, err := s.GetBatch("B1")
715		if err != nil {
716			t.Fatal(err)
717		}
718		if len(got.Feedings) != 1 {
719			t.Fatalf("同一请求只应产生一次投料，得到 %d 条", len(got.Feedings))
720		}
721		if got.Feedings[0].Grams != "10" {
722			t.Fatalf("投料内容不正确: %+v", got.Feedings[0])
723		}
724	}
