740		defer s2.Close()
741	
742		if _, err := s1.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
743			{MaterialNo: "M1", Grams: "1"},
744		}); err != nil {
745			t.Fatal(err)
746		}
