811	// 跨进程并发：两个进程同时向同一台账投料，数据不互相覆盖。
812	// 本子进程由 TestCrossProcessConcurrent 通过环境变量驱动。
813	func TestHelperProcess(t *testing.T) {
814		if os.Getenv("HELPER_PROCESS") != "1" {
815			return
