825		for i := 0; i < 20; i++ {
826			if _, err := s.AddFeeding(fmt.Sprintf("f-%s-%03d", id, i), "B1", "M1", "1",
827				time.Now(), "登记人"+id); err != nil {
828				fmt.Fprintf(os.Stderr, "helper feed: %v\n", err)
829				os.Exit(1)
830			}
831		}
832		os.Exit(0)
