834	
835	func TestCrossProcessConcurrent(t *testing.T) {
836		dir := t.TempDir()
837		// 父进程先登记配方，避免与子进程的登记请求竞争同一版本。
838		s, err := Open(dir)
839		if err != nil {
840			t.Fatal(err)
841		}
842		if _, err := s.RegisterRecipe("recipe-parent", "R1", "v1", "配方一", []MaterialInput{
843			{MaterialNo: "M1", Grams: "1"},
844		}); err != nil {
845			t.Fatal(err)
846		}
847		if _, err := s.CreateBatch("b-parent", "B1", "R1", "v1", 10); err != nil {
848			t.Fatal(err)
849		}
850		if _, err := s.StartBatch("s-parent", "B1"); err != nil {
851			t.Fatal(err)
852		}
853		s.Close()
854	
855		runHelper := func(id string) error {
856			cmd := exec.Command(os.Args[0], "-test.run=TestHelperProcess")
857			cmd.Env = append(os.Environ(),
858				"HELPER_PROCESS=1",
859				"HELPER_DIR="+dir,
860				"HELPER_ID="+id,
861			)
862			out, err := cmd.CombinedOutput()
863			if err != nil {
864				return fmt.Errorf("%v: %s", err, out)
865			}
866			return nil
867		}
868	
869		var wg sync.WaitGroup
870		errs := make(chan error, 2)
871		for _, id := range []string{"A", "B"} {
872			wg.Add(1)
873			go func(id string) {
874				defer wg.Done()
875				errs <- runHelper(id)
876			}(id)
877		}
878		wg.Wait()
879		close(errs)
880		for err := range errs {
881			if err != nil {
882				t.Fatalf("子进程失败: %v", err)
883			}
884		}
885	
886		s2, err := Open(dir)
887		if err != nil {
888			t.Fatal(err)
889		}
890		defer s2.Close()
891		got, err := s2.GetBatch("B1")
892		if err != nil {
893			t.Fatal(err)
894		}
895		if len(got.Feedings) != 40 {
896			t.Fatalf("两个进程共应登记 40 条投料，得到 %d 条（数据被覆盖）", len(got.Feedings))
897		}
898		seqs := map[int]bool{}
899		for _, f := range got.Feedings {
900			if seqs[f.Seq] {
901				t.Fatalf("投料序号重复: %d", f.Seq)
902			}
903			seqs[f.Seq] = true
904		}
905		if got.Materials[0].ActualGrams != "40" {
906			t.Fatalf("累计实投应为 40，得到 %s", got.Materials[0].ActualGrams)
907		}
908	}
