		}
		sum := sums[f.MaterialNo]
		if f.GramsMilli > maxGramsMilli-sum {
			return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
				ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
		}
		sums[f.MaterialNo] = sum + f.GramsMilli
	}
	return nil
}

