				{Seq: 1, MaterialNo: "M1", GramsMilli: 1000, Time: time.Now(), Registrar: "张三"},
				{Seq: 2, MaterialNo: "M2", GramsMilli: 500, Time: time.Now(), Registrar: "李四"},
				{Seq: 3, MaterialNo: "M1", GramsMilli: 250, Time: time.Now(), Registrar: "王五"},
